"""A realistic archive generated by driving TENT objects: two auction series, assets and neighbors, prices with
revisions, scheduled powers, convergence flags, a curve with versions, and a few meter readings."""
import json
import random
import shutil
from datetime import timedelta
from pathlib import Path

import pandas as pd
import pytest
import sqlalchemy as sa

from tent.containers.vertex import Vertex
from tent.utils.timer import Timer
from tent_analysis.data import Source

TENT_ROOT = Path(__file__).resolve().parents[2] / 'TENT'
SAMPLE_CONFIG = TENT_ROOT / 'sample_configs' / 'tn.campus.json'


def _mock_tn_class():
    """TENT's MockTN, loaded by file path so TENT's `tests` package does not collide with this one."""
    import importlib.util
    spec = importlib.util.spec_from_file_location('tent_mock_tn', TENT_ROOT / 'tests' / 'mock_tn.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.MockTN


def build_archive(url: str, actor: str, price_scale: float = 1.0, seed: int = 1, tz: str = 'UTC',
                  orders: bool = True) -> dict:
    MockTN = _mock_tn_class()
    rng = random.Random(seed)
    Timer.simulation = False
    with open(SAMPLE_CONFIG) as f:
        configs = json.load(f)
    configs['data_manager']['db_params']['url'] = url
    configs['actor_id'] = actor
    configs['organization_id'] = 'PNNL'
    configs['tz'] = tz
    if orders:
        # A MatchingEngine series declared in the configuration, so its order-book tables are created with the node's.
        engine = dict(configs['market_series'][0], name='Matching_Market', market_class_name='MatchingEngine',
                      market_module_name='tent.market.matching_engine', initial_market_state='Negotiation',
                      duration_negotiation=600, refined_series=None)
        for key in ('price_model', 'method', 'actuate_assets', 'duality_gap_threshold'):
            engine.pop(key, None)
        configs['market_series'].append(engine)
    tn = MockTN()
    tn.configure_node(configs)
    for _ in range(2):
        tn.step()
    if orders:
        # One negotiation pass of the engine: every entity's active-vertex curve is quoted into the book and each new
        # order is matched, leaving matched legs, superseded parents and standing remainders in the archive.
        from tent.enumerations import OrderStatus
        engine_market = next(s for s in tn.market_series if s.name == 'Matching_Market').newest_market
        engine_market.quote_entities()
        for order in [o for o in engine_market.orderList if o.status in (OrderStatus.NEW, OrderStatus.NEW_REVISED)]:
            engine_market.match(order)
    # Full consensus is recorded only by a ConsensusMarket, so the archive gets one consensus series alongside the
    # auctions, with the same timing as the first auction series. It is never stepped; the fixture writes its data.
    from tent.enumerations import MarketState
    from tent.market.consensus_market import ConsensusMarket
    from tent.market.market_series import MarketSeries
    auction = tn.market_series[0]
    tn.market_series.append(MarketSeries(transactive_node=tn, name='Consensus_Market', market_class=ConsensusMarket,
                                         initial_market_state=MarketState.Negotiation,
                                         duration_negotiation=auction.duration.negotiation.total_seconds(),
                                         duration_delivery_lead=auction.duration.delivery_lead.total_seconds(),
                                         interval_duration=auction.duration.market_interval.total_seconds(),
                                         intervals_to_clear=auction.intervals_to_clear))
    entities = list(tn.local_assets) + list(tn.neighbors)
    for series in tn.market_series:
        for market in series:
            for k, ti in enumerate(market.time_intervals):
                base = price_scale * (0.04 + 0.03 * ((k % 24) / 23.0))
                market.marginal_prices.update(ti, round(base * 0.9, 5))        # negotiation round 1
                market.marginal_prices.update(ti, round(base, 5))              # cleared
                for j, entity in enumerate(entities):
                    sign = 1.0 if j % 3 == 0 else -1.0
                    power = sign * (20.0 + 10.0 * j + 15.0 * rng.random())
                    entity.scheduled_powers.update(ti, round(power * 0.95, 3))
                    entity.scheduled_powers.update(ti, round(power, 3))
                for neighbor in tn.neighbors:
                    neighbor.convergence_flags.update(ti, True)
    asset = tn.local_assets[0]
    market = tn.market_series[0].newest_market
    ti = market.time_intervals[0]
    asset.active_vertices.update(ti, [Vertex(price=0.02, quantity=-60.0), Vertex(price=0.08, quantity=-20.0)])
    asset.active_vertices.update(ti, [Vertex(price=0.03, quantity=-55.0), Vertex(price=0.09, quantity=-15.0)])
    # Phase 2 data: a system curve per interval, consensus flags, and sent/received signals for one neighbor.
    for ti in market.time_intervals[:6]:
        market.active_vertices.update(ti, [Vertex(price=0.02, quantity=-80.0), Vertex(price=0.06, quantity=0.0),
                                           Vertex(price=0.10, quantity=90.0)])
    transactive = [n for n in tn.neighbors if n.transactive]
    consensus_market = tn.market_series[-1].newest_market
    for ti in consensus_market.time_intervals:
        for n in transactive:
            n.convergence_flags.update(ti, ti is not consensus_market.time_intervals[1])
    consensus_market.converged = True
    consensus_market.record_consensus()
    if transactive:
        from tent.containers.transactive_signal import TransactiveSignal
        from tent.enumerations import SignalDirection
        neighbor = transactive[0]
        sent = TransactiveSignal(market=market, neighbor=neighbor, direction=SignalDirection.sent, signal_time=Timer.now())
        received = TransactiveSignal(market=market, neighbor=neighbor, direction=SignalDirection.received,
                                     signal_time=Timer.now() + timedelta(seconds=30))
        # The received signal is stated from the remote side (TENT convention), so its quantities carry the opposite
        # sign: the remote offers +45 kW where the local side asks -50 kW, and so on.
        for ti in market.time_intervals[:4]:
            sent.update(ti, [Vertex(price=0.03, quantity=-50.0), Vertex(price=0.09, quantity=30.0)], archive=False)
            received.update(ti, [Vertex(price=0.03, quantity=45.0), Vertex(price=0.09, quantity=-36.0)], archive=False)
        sent.archive()
        received.archive()
    if tn.meter_points:
        meter = tn.meter_points[0]
        t0 = Timer.now()
        for i in range(6):
            meter.set_meter_value(100.0 + i, last_update=t0 + timedelta(minutes=10 * i))
    return {'tn': tn, 'entities': entities}


@pytest.fixture(scope='session')
def archive_url(tmp_path_factory):
    url = f'sqlite:///{tmp_path_factory.mktemp("archive") / "campus_a.sqlite"}'
    build_archive(url, actor='campus-A')
    return url


@pytest.fixture(scope='session')
def variant_url(tmp_path_factory):
    url = f'sqlite:///{tmp_path_factory.mktemp("archive") / "campus_b.sqlite"}'
    build_archive(url, actor='campus-B', price_scale=1.2, seed=2)
    return url


@pytest.fixture(scope='session')
def source(archive_url):
    return Source(archive_url, label='campus_a')


@pytest.fixture(scope='session')
def variant(variant_url):
    return Source(variant_url, label='campus_b')


@pytest.fixture(scope='session')
def pacific(tmp_path_factory):
    """The same kind of archive, from a node configured in America/Los_Angeles, without an order book."""
    url = f'sqlite:///{tmp_path_factory.mktemp("archive") / "campus_pacific.sqlite"}'
    build_archive(url, actor='campus-P', tz='America/Los_Angeles', orders=False)
    return Source(url, label='campus_pacific')


@pytest.fixture(scope='session')
def historian(source, tmp_path_factory):
    """The fixture archive plus a VOLTTRON historian (topics/data) and an unrelated table in the same database."""
    path = tmp_path_factory.mktemp('shared') / 'shared.sqlite'
    shutil.copy(source.url.removeprefix('sqlite:///'), path)
    engine = sa.create_engine(f'sqlite:///{path}')
    meta = sa.MetaData()
    topics = sa.Table('topics', meta, sa.Column('topic_id', sa.Integer, primary_key=True), sa.Column('topic_name', sa.Text))
    data = sa.Table('data', meta, sa.Column('ts', sa.DateTime), sa.Column('topic_id', sa.Integer), sa.Column('value_string', sa.Text))
    notes = sa.Table('secret_notes', meta, sa.Column('id', sa.Integer, primary_key=True), sa.Column('note', sa.Text))
    meta.create_all(engine)
    t0 = pd.Timestamp('2017-07-01T00:00Z')
    with engine.begin() as conn:
        conn.execute(topics.insert(), [{'topic_id': 1, 'topic_name': 'campus/building1/OutdoorAirTemperature'},
                                       {'topic_id': 2, 'topic_name': 'campus/building1/Status'},
                                       {'topic_id': 3, 'topic_name': 'campus/building1/Power'}])
        conn.execute(data.insert(), [{'ts': (t0 + pd.Timedelta(minutes=10 * i)).to_pydatetime().replace(tzinfo=None),
                                      'topic_id': 1, 'value_string': str(20.0 + i)} for i in range(4)]
                     + [{'ts': t0.to_pydatetime().replace(tzinfo=None), 'topic_id': 2, 'value_string': '{"mode": "cool"}'}]
                     + [{'ts': (t0 + pd.Timedelta(minutes=10 * i)).to_pydatetime().replace(tzinfo=None),
                         'topic_id': 3, 'value_string': str(1000.0 * i)} for i in range(3)])
        conn.execute(notes.insert(), [{'id': 1, 'note': 'not for the analysis tool'}])
    return Source(f'sqlite:///{path}', label='historian')
